const FILTERS = ['الاسم', 'رقم الهاتف', 'الوظيفة', 'المدينة', 'المؤهل العلمي', 'سنوات الخبرة', 'الحالة', 'الجنس', 'الجنسية', 'تاريخ التقديم'];
