const DESKTOP_ONLY = ['list-columns']; // column chooser applies to the desktop table; mobile uses cards

// ---- one in-page audit used by every page × viewport
async function audit(page, touch) {
  return page.evaluate(touch => {
    const vis = e => e.getClientRects().length > 0 && getComputedStyle(e).visibility !== 'hidden' && !e.closest('.vh');
    const own = e => [...e.childNodes].some(n => n.nodeType === 3 && n.textContent.trim());
    const SKIP = ['SCRIPT', 'STYLE', 'OPTION', 'OPTGROUP', 'SELECT', 'TEXTAREA', 'TITLE'];
    const texts = [...document.body.querySelectorAll('*')].filter(e => !SKIP.includes(e.tagName) && own(e) && vis(e));
    const name = e => `${e.tagName.toLowerCase()}${e.className && typeof e.className === 'string' ? '.' + e.className.split(' ')[0] : ''}: ${e.textContent.trim().slice(0, 30)}`;
    const tiny = [...new Set(texts.filter(e => parseFloat(getComputedStyle(e).fontSize) < 12).map(name))];
    const clipped = texts.filter(e => {
      const cs = getComputedStyle(e); if (e.clientWidth === 0 || ['auto', 'scroll'].includes(cs.overflowX)) return false;
      return e.scrollWidth - e.clientWidth > 1 || (e.scrollHeight - e.clientHeight > 1 && cs.overflowY !== 'visible');
    }).map(name);
    const TARGETS = 'a[href], button, select, textarea, input:not([type=radio]):not([type=checkbox]):not([type=file]):not([type=hidden]), label.tap, label.drop, [role=button]';
    const small = touch ? [...document.querySelectorAll(TARGETS)].filter(vis).filter(e => {
      const r = e.getBoundingClientRect(); return r.width < 43.5 || r.height < 43.5;
    }).map(name) : [];
    const controls = [...document.querySelectorAll('input:not([type=hidden]), select, textarea')];
    const unlabeled = controls.filter(e => {
      const l = [...(e.labels || [])].map(x => x.textContent.trim()).join('');
      const by = (e.getAttribute('aria-labelledby') || '').split(/\s+/).filter(Boolean).map(id => document.getElementById(id)?.textContent.trim() || '').join('');
      return !(l || by || (e.getAttribute('aria-label') || '').trim());
    }).map(e => e.id || e.name || e.type);
    const dialogs = [...document.querySelectorAll('[role=dialog]')].filter(vis).map(d => {
      const b = d.getBoundingClientRect(), x = d.querySelector('.x')?.getBoundingClientRect(), body = d.querySelector('.dbody');
      const foot = [...d.querySelectorAll('.dfoot .btn')].map(e => e.getBoundingClientRect());
      return {
        inside: b.top >= -1 && b.left >= -1 && b.right <= innerWidth + 1 && b.bottom <= innerHeight + 1,
        scrollable: !body || body.scrollHeight <= body.clientHeight + 1 || ['auto', 'scroll'].includes(getComputedStyle(body).overflowY),
        bodyUsable: !body || body.clientHeight >= Math.min(80, body.scrollHeight),
        close: !!x && x.top >= 0 && x.bottom <= innerHeight + 1 && x.width >= 44 && x.height >= 44,
        footer: foot.every(r => r.top >= 0 && r.bottom <= innerHeight + 1),
        labelled: !!d.getAttribute('aria-labelledby') && !!document.getElementById(d.getAttribute('aria-labelledby'))?.textContent.trim(),
      };
    });
    return { lang: document.documentElement.lang, dir: document.documentElement.dir, overflowX: document.documentElement.scrollWidth > innerWidth + 1,
      tiny, clipped, small, unlabeled, dialogs, h1: document.querySelectorAll('h1').length };
  }, touch);
}

async function contract(page, ti, file) {
  await page.goto(C + file + '.html');
  const r = await audit(page, !!ti.project.use.hasTouch);
  const en = file === 'en-careers';
  expect.soft(r.lang, 'lang').toBe(en ? 'en' : 'ar');
  expect.soft(r.dir, 'dir').toBe(en ? 'ltr' : 'rtl');
  expect.soft(r.h1, 'exactly one h1').toBe(1);
  expect.soft(r.overflowX, 'horizontal overflow').toBe(false);
  expect.soft(r.clipped, 'clipped text').toEqual([]);
  expect.soft(r.tiny, 'text < 12px').toEqual([]);
  expect.soft(r.small, 'touch targets < 44px').toEqual([]);
  expect.soft(r.unlabeled, 'controls without a label').toEqual([]);
  for (const d of r.dialogs) expect.soft(d, 'dialog fits the screen').toEqual({ inside: true, scrollable: true, bodyUsable: true, close: true, footer: true, labelled: true });
  const axe = await new AxeBuilder({ page }).withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa']).analyze();
  const blocking = axe.violations.filter(v => ['serious', 'critical'].includes(v.impact));
  if (blocking.length) await ti.attach(`axe-${file}.json`, { body: JSON.stringify(blocking, null, 2), contentType: 'application/json' });
  expect.soft(blocking.map(v => `${v.id} (${v.nodes.length}): ${v.nodes[0]?.target}`), 'axe serious/critical').toEqual([]);
  return r;
}

test.describe('careers · public pages (page × viewport)', () => {
  for (const p of PUBLIC) test(`${p} · layout, labels, axe @careers @responsive @a11y`, async ({ page }, ti) => { await contract(page, ti, p); });
});

test.describe('careers · owner dashboard (desktop ≥ 1024 · mobile below)', () => {
  for (const k of DASH) test(`${k} · layout, labels, axe, dialogs @careers @responsive @a11y`, async ({ page }, ti) => {
    test.skip(!isDesk(ti) && DESKTOP_ONLY.includes(k), 'desktop-only screen');
    const r = await contract(page, ti, `${isDesk(ti) ? 'd' : 'm'}-${k}`);
    if (/filters|confirm|quickview|columns|export/.test(k)) expect(r.dialogs.length, 'dialog present').toBe(1);
  });
});

// ---- behaviour on every viewport
const group = (page, name) => page.getByRole('group', { name, exact: true });

test.describe('careers · form behaviour', () => {
  test('error state: summary at top (role=alert) links to fields; inline errors are not colour-only @careers @a11y', async ({ page }) => {
    for (const f of ['form-a-errors', 'form-b-errors']) {
      await page.goto(C + f + '.html');
      const sum = page.locator('.esum[role=alert]');
      await expect(sum).toBeVisible();
      const links = await sum.locator('a').evaluateAll(as => as.map(a => ({ t: a.textContent.trim(), target: !!document.getElementById(a.hash.slice(1)) })));
      expect(links.length).toBeGreaterThan(0);
      expect(links.every(l => l.target && l.t)).toBe(true);
      const inline = await page.locator('.err').evaluateAll(es => es.map(e => e.textContent.trim()));
      expect(inline.length).toBe(links.length);
      expect(inline.every(t => t.startsWith('خطأ:'))).toBe(true); // text + icon + border, not colour alone
      const invalid = await page.locator('[aria-invalid=true]').evaluateAll(es => es.every(e => (e.getAttribute('aria-describedby') || '').includes('e-')));
      expect(invalid).toBe(true);
    }
  });

  test('variant A: empty submit → focused error summary listing every field @careers', async ({ page }) => {
    await page.goto(C + 'form-a.html');
    await page.getByRole('button', { name: 'إرسال الطلب' }).click();
    const sum = page.locator('.esum[role=alert]');
    await expect(sum).toBeFocused();
    await expect(sum).toBeInViewport();
    expect(await sum.locator('a').count()).toBe(FIELDS.length);
  });

  test('variant B: next on an empty step → step error summary; ≤ 4 steps with progress @careers', async ({ page }) => {
    await page.goto(C + 'form-b.html');
    await expect(page.locator('.prog-t')).toHaveText(/الخطوة 1 من 4/);
    expect(await page.locator('.step').count()).toBeLessThanOrEqual(4);
    await page.getByRole('button', { name: 'التالي' }).click();
    await expect(page.locator('.esum[role=alert]')).toBeFocused();
    await expect(page.locator('.esum[role=alert]')).toBeInViewport();
  });

  test('nationality: conditional fields appear and become required @careers', async ({ page }) => {
    await page.goto(C + 'form-a.html');
    const nid = page.getByLabel('الرقم الوطني'), natx = page.getByLabel('ما هي جنسيتك؟'), doc = page.getByLabel('رقم جواز السفر أو رقم وثيقة الهوية');
    for (const l of [nid, natx, doc]) await expect(l).toBeHidden();
    await group(page, 'الجنسية').getByLabel('أردني', { exact: true }).check();
    await expect(nid).toBeVisible(); await expect(nid).toHaveAttribute('required', '');
    await expect(natx).toBeHidden();
    await group(page, 'الجنسية').getByLabel('غير أردني', { exact: true }).check();
    await expect(nid).toBeHidden();
    for (const l of [natx, doc]) { await expect(l).toBeVisible(); await expect(l).toHaveAttribute('required', ''); }
  });

  test('getByLabel reaches every owner field in A and B @careers @a11y', async ({ page }) => {
    for (const f of ['form-a', 'form-b']) {
      await page.goto(C + f + '.html');
      for (const l of ['الاسم الكامل', 'رقم الهاتف', 'البريد الإلكتروني', 'اليوم', 'الشهر', 'السنة', 'الحالة الاجتماعية', 'المدينة', 'المنطقة',
        'المؤهل العلمي', 'سنوات الخبرة', 'الوظيفة المتقدم لها', 'الراتب المتوقع', 'ملاحظات إضافية', UPLOAD, 'الرقم الوطني']) expect(await page.getByLabel(l).count(), l).toBe(1);
      expect(await page.getByLabel('المرفقات').and(page.locator('input[type=file]')).count()).toBe(1); // the section is also named المرفقات
      expect(await page.getByLabel(CONSENT).count()).toBe(1);
      for (const g of ['الجنس', 'الجنسية', 'هل لديك خبرة سابقة في نفس المجال أو الوظيفة التي تتقدم لها؟', 'هل تعمل حاليًا؟', 'هل لديك رخصة قيادة؟', 'تاريخ الميلاد'])
        expect(await page.getByRole('group', { name: g, exact: true, includeHidden: true }).count(), g).toBe(1); // B keeps later steps hidden
    }
  });
});

